"""Read-only pull of O-line inputs for FBS games in 2026 weeks 1-5 and 7.

Stores per-player totals only (no raw play rows). Writes to PFF_WORK_DIR (default data/, gitignored).
"""
import sys, os, json, time, collections
sys.path.insert(0, os.environ.get("PFF_PIPELINE_DIR", "/Users/kristinarash/DEV/Football/PFF_Data_Project"))
from dotenv import load_dotenv
load_dotenv(os.path.join(os.environ.get("PFF_PIPELINE_DIR", "/Users/kristinarash/DEV/Football/PFF_Data_Project"), ".env"))
from src.ingest.pff_client import PFFClient
OUT = os.environ.get("PFF_WORK_DIR", "data")
os.makedirs(OUT, exist_ok=True)
WEEKS = {1, 2, 3, 4, 5, 7}
c = PFFClient()
teams = c.get_teams(2026)
t = teams if isinstance(teams, list) else teams.get("teams", [])
fbs = {str(x.get("franchise_id")) for x in t if any(g.get("name") == "FBS" for g in (x.get("groups") or []))}
games = c.get_games(2026)
g = games if isinstance(games, list) else games.get("games", [])
sel = [x for x in g if x.get("week") in WEEKS and (str(x.get("home_franchise_id")) in fbs or str(x.get("away_franchise_id")) in fbs)]
grades, blk, pres, pp, fails = [], collections.defaultdict(lambda: [0, 0.0, 0]), collections.defaultdict(lambda: [0, 0.0, 0]), collections.Counter(), []
pos_counter = collections.Counter()
t0 = time.time()
for i, x in enumerate(sel, 1):
    gid, wk = str(x["id"]), int(x["week"])
    try:
        for r in c.get_game_grade(gid).get("game_grade") or []:
            pos_counter[str(r.get("position"))] += 1
            grades.append({"game_id": gid, "week": wk, "team_id": str(r.get("team_id")), "player_id": str(r.get("player_id")),
                           "position": r.get("position"), "snaps": r.get("overall_snaps"), "offense": r.get("offense"), "pass": r.get("pass")})
    except Exception as e:
        fails.append(("grade", gid, type(e).__name__))
    try:
        for r in c.get_premium_game(gid, "all_blocking").get("all_blocking") or []:
            k = (gid, str(r.get("player_id")))
            blk[k][0] += 1
            if isinstance(r.get("player_grade"), (int, float)):
                blk[k][1] += r["player_grade"]; blk[k][2] += 1
    except Exception as e:
        fails.append(("all_blocking", gid, type(e).__name__))
    try:
        for r in c.get_premium_game(gid, "pressure").get("pressure") or []:
            k = (gid, str(r.get("offensive_player_id")))
            pres[k][0] += 1
            if isinstance(r.get("offensive_grade"), (int, float)):
                pres[k][1] += r["offensive_grade"]; pres[k][2] += 1
    except Exception as e:
        fails.append(("pressure", gid, type(e).__name__))
    try:
        for r in c.get_premium_game(gid, "pass_protection").get("pass_protection") or []:
            pp[(gid, str(r.get("player_id")))] += 1
    except Exception as e:
        fails.append(("pass_protection", gid, type(e).__name__))
    if i % 50 == 0:
        print(f"{i}/{len(sel)} {time.time()-t0:.0f}s fails={len(fails)}", flush=True)
def dump(d):
    return [{"game_id": k[0], "player_id": k[1], "rows": v[0], "grade_sum": v[1], "grade_n": v[2]} for k, v in d.items()]
json.dump({"grades": grades, "blocking": dump(blk), "pressure": dump(pres),
           "pass_protection": [{"game_id": k[0], "player_id": k[1], "rows": v} for k, v in pp.items()],
           "fails": fails, "positions": pos_counter}, open(os.path.join(OUT, "oline_pull.json"), "w"))
print("DONE games", len(sel), "grade rows", len(grades), "fails", len(fails), "positions", dict(pos_counter.most_common(30)), flush=True)
PY
