"""Read-only pull of per-player event counts for LB, DB and RB models (one season per run).

Counts per (game, player): tackles (A22 all_tackling, tackler_player_id), runs (premium rushing, runner_player_id),
pass-rush rows (premium pass_rush, player_id). Stores totals only. Writes data/pos_<season>.json.
Field-to-role mapping is unverified against the PFF docs, as for the O-line.
"""
import sys, os, json, time, collections
sys.path.insert(0, os.environ.get("PFF_PIPELINE_DIR", "/Users/kristinarash/DEV/Football/PFF_Data_Project"))
from dotenv import load_dotenv
load_dotenv(os.path.join(os.environ.get("PFF_PIPELINE_DIR", "/Users/kristinarash/DEV/Football/PFF_Data_Project"), ".env"))
from src.ingest.pff_client import PFFClient
OUT = os.environ.get("PFF_WORK_DIR", "data")
SEASON = int(os.environ["PFF_SEASON"])
WEEKS = {1, 2, 3, 4, 5, 7}
c = PFFClient()
def rows_of(p):
    if isinstance(p, list):
        return p
    return next((v for v in p.values() if isinstance(v, list)), []) if isinstance(p, dict) else []
games = c.get_games(SEASON); g = games if isinstance(games, list) else games.get("games", [])
teams = c.get_teams(SEASON); t = teams if isinstance(teams, list) else teams.get("teams", [])
fbs = {str(x.get("franchise_id")) for x in t if any(gg.get("name") == "FBS" for gg in (x.get("groups") or []))}
sel = [x for x in g if x.get("week") in WEEKS and (str(x.get("home_franchise_id")) in fbs or str(x.get("away_franchise_id")) in fbs)]
tack, runs, prush, fails = collections.Counter(), collections.Counter(), collections.Counter(), []
t0 = time.time()
for i, x in enumerate(sel, 1):
    gid = str(x["id"])
    try:
        for r in rows_of(c._get(f"/v1/a22/ncaa/games/{gid}/all_tackling")):
            if r.get("tackler_player_id") is not None:
                tack[(gid, str(r["tackler_player_id"]))] += 1
    except Exception as e:
        fails.append(("tackling", gid, type(e).__name__))
    try:
        for r in rows_of(c.get_premium_game(gid, "rushing")):
            if r.get("runner_player_id") is not None:
                runs[(gid, str(r["runner_player_id"]))] += 1
    except Exception as e:
        fails.append(("rushing", gid, type(e).__name__))
    try:
        for r in rows_of(c.get_premium_game(gid, "pass_rush")):
            if r.get("player_id") is not None:
                prush[(gid, str(r["player_id"]))] += 1
    except Exception as e:
        fails.append(("pass_rush", gid, type(e).__name__))
    if i % 100 == 0:
        print(f"{i}/{len(sel)} {time.time()-t0:.0f}s fails={len(fails)}", flush=True)
def dump(cnt, name):
    return [{"game_id": k[0], "player_id": k[1], name: v} for k, v in cnt.items()]
json.dump({"season": SEASON, "tackles": dump(tack, "n_tackles"), "runs": dump(runs, "n_runs"), "pass_rush": dump(prush, "n_pass_rush"), "fails": fails},
          open(os.path.join(OUT, f"pos_{SEASON}.json"), "w"))
print("DONE season", SEASON, "games", len(sel), "fails", len(fails), flush=True)
PY
